--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageTakeoutTipsPopUp.prefab
---@class CoffeeTakeoutTrackListCellNode
---@field Env                            CoffeeTakeoutTrackListCellNode
---@field controller                        Engine.Modules.LuaBehaviour
---@field FontStyleButton                UnityEngine.RectTransform
---@field Lock                            UnityEngine.RectTransform
---@field Finish                            UnityEngine.RectTransform
---@field Underway                        UnityEngine.RectTransform
---@field TextDesc                        UnityEngine.RectTransform
---@field VIPTeam                        UnityEngine.RectTransform
---@field NormalTeam                        UnityEngine.RectTransform
local CoffeeTakeoutTrackListCellNode = Class('CoffeeTakeoutTrackListCellNode')

function CoffeeTakeoutTrackListCellNode:__init()
    self.teamId = nil
    self.timeTickEvent = nil
    self.orderPlayerId = nil
    self.cb = nil
end

function CoffeeTakeoutTrackListCellNode:__delete()
    self.teamId = nil
    self.timeTickEvent = nil
    self.orderPlayerId = nil
    self.cb = nil
end

function CoffeeTakeoutTrackListCellNode:Awake()
    self.progressingText = self.Underway.transform:Find("Time/TextNumber"):GetComponent(typeof(TextMeshProUGUI))
    if self.progressingText then
        self.progressingText.text = ''
    end
    self.timeTickEvent = Events.AddListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, Bind(self, self.OnTimeTick))
    local buttonNode = self.controller.transform:Find("BtnNode")
    if buttonNode then
        SetButtonAction(buttonNode.gameObject, function()
            ---@type MaidCoffeePlayerComponent
            local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
            local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(self.teamId)
            if status == MaidCoffeeConstants.TakeOutStatus.IDLE then
                ---空闲中
            elseif status == MaidCoffeeConstants.TakeOutStatus.LOCKED then
                ---锁定中
                print('--->>', self.teamId)
                local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(self.teamId)
                local vip = checkNumber(vo.vip)
                if vip == 1 then
                    ---直接打开充值页面
                    local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIWelfareMainDialog, parameters = { selectedIndex = WelfareConstants.OpenIds.SubScribe } })
                    --UIModule.CloseDialogById(Constants.UITypeIds.OverseaManageTakeoutTipsPopUp)
                end
            elseif status == MaidCoffeeConstants.TakeOutStatus.PROGRESSING then
                ---进行中的订单队伍
                --[[if self.cb then
                    local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByTeamId(self.teamId)
                    ----订单数据，进行中的数据
                    self.cb(dojo)
                end]]
            end
        end)
    end
    SetButtonAction(self.FontStyleButton, function()
        ----已完成领取奖励的按钮
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByTeamId(self.teamId)
        if not dojo then return end
        GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
            type = 1, orderId = dojo.id
        }, function(request, response)
            if checkNumber(response.errCode) == 0 then
                ---成功了
                local rdata = checkTable(response.data)
                local rewards = checkTable(rdata.rewards)
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local v = maidCoffeePlayerComponent:GetCardsByTeamId(dojo.teamId)
                for _, id in pairs(v) do
                    cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                end
                if #rewards > 0 then
                    GoodsUtils.DrawRewards(rewards)
                    ---关闭当前的页面
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = rdata.rewards }
                            }
                    )
                end
                Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = dojo, isNewOrder = 1 })
            end
        end)
    end)
end

function CoffeeTakeoutTrackListCellNode:FreshUI(teamId, cb)
    teamId = checkNumber(teamId)
    self.cb = cb
    self.teamId = teamId
    if self.progressingText then
        self.progressingText.text = ''
    end
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
    ---@type MaidCoffeeClerkSettingVo
    local vo = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(teamId)
    local vip = checkNumber(vo.vip)
    KTool.SetActive(self.NormalTeam.gameObject, vip ~= 1)
    KTool.SetActive(self.VIPTeam.gameObject, vip == 1)
    if vip ~= 1 then
        CfUtils.FillText(self.NormalTeam.transform:Find("TextName"), vo.carName)
    else
        CfUtils.FillText(self.VIPTeam.transform:Find("TextName"), vo.carName)
    end
    KTool.SetActive(self.Underway.gameObject, status == MaidCoffeeConstants.TakeOutStatus.PROGRESSING)
    if status == MaidCoffeeConstants.TakeOutStatus.IDLE then
        KTool.SetActive(self.Lock.gameObject, true)
        KTool.SetActive(self.Finish.gameObject, false)
        ---空闲中
        CfUtils.FillText(self.TextDesc, localize('空闲中'))
        local jumpActionTrans = self.Lock.transform:Find("FunctionJump")
        if jumpActionTrans then
            KTool.SetActive(jumpActionTrans.gameObject, false)
        end
        local maskTrans = self.Lock.transform:Find("ImgMask")
        if maskTrans then
            KTool.SetActive(maskTrans.gameObject, false)
        end
        local ImgLockTrans = self.Lock.transform:Find("ImgLock")
        if ImgLockTrans then
            KTool.SetActive(ImgLockTrans.gameObject, false)
        end

    elseif status == MaidCoffeeConstants.TakeOutStatus.LOCKED then
        ---锁定中
        KTool.SetActive(self.Lock.gameObject, true)
        local maskTrans = self.Lock.transform:Find("ImgMask")
        if maskTrans then
            KTool.SetActive(maskTrans.gameObject, true)
        end
        local ImgLockTrans = self.Lock.transform:Find("ImgLock")
        if ImgLockTrans then
            KTool.SetActive(ImgLockTrans.gameObject, true)
        end
        local jumpActionTrans = self.Lock.transform:Find("FunctionJump")
        if jumpActionTrans then
            KTool.SetActive(jumpActionTrans.gameObject, vip == 1)
        end
        KTool.SetActive(self.Finish.gameObject, false)
        if vip == 1 then
            CfUtils.FillText(self.TextDesc, localize('开通权益卡解锁'))
        else
            local desc = GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum)
            CfUtils.FillText(self.TextDesc, desc)
        end
    else
        KTool.SetActive(self.Lock.gameObject, false)
        KTool.SetActive(self.Finish.gameObject, status == MaidCoffeeConstants.TakeOutStatus.FINISHED)
        ---配送中 或者已完成
        ---@type table
        local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersByTeamId(teamId)
        if dojo then
            self.orderPlayerId = checkNumber(dojo.id)
        end
        if checkNumber(dojo.area) > 0 then
            local areaVo = ActionUtils.GetRegionPrimaryMapVo(checkNumber(dojo.area))
            if status == MaidCoffeeConstants.TakeOutStatus.PROGRESSING then
                CfUtils.FillText(self.TextDesc, localize('正在_name_配送订单', {_name_ = areaVo.name}))
            else
                ---Finish已完成
                CfUtils.FillText(self.TextDesc, localize('_name_订单已送达', {_name_ = areaVo.name}))
            end
        end
    end
end

function CoffeeTakeoutTrackListCellNode:OnTimeTick(orderId, text)
    --正在配送<size=50><color=#d7184a>2:20:00</color></size>
    if self.orderPlayerId and checkNumber(self.orderPlayerId) == checkNumber(orderId) then
        if type(text) == 'string' then
            if self.progressingText then
                self.progressingText.text = text
            end
        elseif text == 1 then
            ---已完成
            ---@type MaidCoffeePlayerComponent
            local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
            local dojo = maidCoffeePlayerComponent:GetTakeoutOrdersById(self.orderPlayerId)
            dojo.status = MaidCoffeeConstants.TakeOutStatus.FINISHED
            ---数据改变 刷新界面
            Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED)
        end
    end
end


function CoffeeTakeoutTrackListCellNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.EVENT_CONFIRM_TIME_TICK, self.timeTickEvent)
    self.timeTickEvent = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CoffeeTakeoutTrackListCellNode